        verifyingKey.beta = beta;
        verifyingKey.gamma = gamma;
        verifyingKey.delta = delta;
    }

    /**
     * @dev Get verifying key
     */
    function getVerifyingKey() external view returns (VerifyingKey memory) {
        return verifyingKey;
    }
